/* Local lightweight Anime.js-compatible subset for splash animations (offline-safe). */
(function (global) {
  "use strict";

  function toArray(targets) {
    if (!targets) return [];
    if (typeof targets === "string") return Array.from(document.querySelectorAll(targets));
    if (targets instanceof Element) return [targets];
    if (Array.isArray(targets)) {
      return targets.flatMap(function (t) {
        if (typeof t === "string") return Array.from(document.querySelectorAll(t));
        return t ? [t] : [];
      });
    }
    return [];
  }

  function parseNumUnit(value) {
    if (typeof value === "number") return { n: value, u: "" };
    var match = String(value).trim().match(/^(-?\d+(?:\.\d+)?)([a-z%]*)$/i);
    return match ? { n: Number(match[1]), u: match[2] || "" } : { n: 0, u: "" };
  }

  function makeTransformFrame(scaleVal, translateYVal) {
    var parts = [];
    if (scaleVal != null) parts.push("scale(" + scaleVal + ")");
    if (translateYVal != null) parts.push("translateY(" + translateYVal + "px)");
    return parts.length ? parts.join(" ") : undefined;
  }

  function mapEasing(easing) {
    var map = {
      easeOutQuad: "cubic-bezier(0.25, 0.46, 0.45, 0.94)",
      easeOutSine: "cubic-bezier(0.39, 0.575, 0.565, 1)",
      easeOutCubic: "cubic-bezier(0.215, 0.61, 0.355, 1)",
      easeInOutSine: "cubic-bezier(0.445, 0.05, 0.55, 0.95)",
      linear: "linear"
    };
    return map[easing] || easing || "ease";
  }

  function getDelay(delay, index, target) {
    if (typeof delay === "function") return Number(delay(target, index)) || 0;
    return Number(delay) || 0;
  }

  function anime(options) {
    var opts = options || {};
    var targets = toArray(opts.targets);
    var duration = Number(opts.duration) || 1000;
    var easing = mapEasing(opts.easing);
    var iterations = opts.loop === true ? Infinity : (Number(opts.loop) || 1);
    var direction = opts.direction === "alternate" ? "alternate" : "normal";

    var animations = targets.map(function (target, index) {
      var key0 = {};
      var key1 = {};
      var fromScale = null;
      var toScale = null;
      var fromTranslateY = null;
      var toTranslateY = null;

      if (opts.opacity) {
        key0.opacity = opts.opacity[0];
        key1.opacity = opts.opacity[1];
      }
      if (opts.width) {
        key0.width = opts.width[0];
        key1.width = opts.width[1];
      }
      if (opts.scale) {
        fromScale = opts.scale[0];
        toScale = opts.scale[1];
      }
      if (opts.translateY) {
        fromTranslateY = opts.translateY[0];
        toTranslateY = opts.translateY[1];
      }

      var t0 = makeTransformFrame(fromScale, fromTranslateY);
      var t1 = makeTransformFrame(toScale, toTranslateY);
      if (t0) key0.transform = t0;
      if (t1) key1.transform = t1;

      var delay = getDelay(opts.delay, index, target);
      if (typeof target.animate === "function") {
        return target.animate([key0, key1], {
          duration: duration,
          delay: delay,
          easing: easing,
          fill: "forwards",
          iterations: iterations,
          direction: direction
        });
      }

      setTimeout(function () {
        Object.keys(key0).forEach(function (k) { target.style[k] = key0[k]; });
        setTimeout(function () {
          Object.keys(key1).forEach(function (k) { target.style[k] = key1[k]; });
        }, 16);
      }, delay);
      return null;
    });

    return { animations: animations };
  }

  anime.stagger = function (step) {
    var s = Number(step) || 0;
    return function (_target, index) {
      return index * s;
    };
  };

  anime.timeline = function (baseOptions) {
    var base = baseOptions || {};
    var cursor = 0;

    function parseOffset(offset) {
      if (offset == null) return cursor;
      if (typeof offset === "number") return offset;
      if (typeof offset === "string") {
        var m = offset.match(/^([+-])=(\d+(?:\.\d+)?)$/);
        if (m) {
          var delta = Number(m[2]);
          return m[1] === "-" ? cursor - delta : cursor + delta;
        }
      }
      return cursor;
    }

    return {
      add: function (stepOptions, offset) {
        var startAt = parseOffset(offset);
        var merged = Object.assign({}, base, stepOptions || {});
        var originalDelay = merged.delay;
        merged.delay = typeof originalDelay === "function"
          ? function (target, index) {
              return startAt + getDelay(originalDelay, index, target);
            }
          : startAt + (Number(originalDelay) || 0);

        anime(merged);

        var targets = toArray(merged.targets);
        var maxDelay = 0;
        for (var i = 0; i < targets.length; i += 1) {
          var d = getDelay(originalDelay, i, targets[i]);
          if (d > maxDelay) maxDelay = d;
        }
        var dur = Number(merged.duration || base.duration) || 0;
        cursor = Math.max(cursor, startAt + maxDelay + dur);
        return this;
      }
    };
  };

  global.anime = anime;
})(window);
